pub struct Framebuffer { pub width: u32, pub height: u32, pixels: Vec<u32> }
impl Framebuffer { pub fn new(width: u32, height: u32) -> Result<Self, &'static str> { let count = (width as usize).checked_mul(height as usize).ok_or("framebuffer size overflow")?; if count == 0 { return Err("framebuffer dimensions are zero"); } Ok(Self { width, height, pixels: vec![0; count] }) } pub fn clear(&mut self, color: u32) { self.pixels.fill(color); } pub fn set_pixel(&mut self, x: u32, y: u32, color: u32) -> Result<(), &'static str> { if x >= self.width || y >= self.height { return Err("pixel outside framebuffer"); } self.pixels[(y * self.width + x) as usize] = color; Ok(()) } pub fn pixels(&self) -> &[u32] { &self.pixels } }
